:root {
  --pv-bg: #f4f6f8;
  --pv-surface: #ffffff;
  --pv-text: #152033;
  --pv-muted: #4b5568;
  --pv-border: #d5dbe3;
  --pv-accent: #1d4e78;
  --pv-accent-contrast: #ffffff;
  --pv-accent-hover: #14385a;
  --pv-focus: #0f3d6b;
  --pv-panel: #0f1c2e;
  --pv-font-display: clamp(2.1rem, 4.4vw, 3.15rem);
  --pv-font-section: clamp(1.45rem, 2.4vw, 1.85rem);
  --pv-font-body: 1.05rem;
  --pv-font-caption: 0.82rem;
  --pv-font-eyebrow: 0.75rem;
  --pv-space-section: 5rem;
  --pv-space-stack: 1.25rem;
  --pv-space-gutter: 1.5rem;
  --pv-radius-sm: 6px;
  --pv-radius-md: 10px;
  --pv-radius-lg: 16px;
  --pv-shadow-subtle: 0 1px 2px rgba(21,32,51,0.06);
  --pv-shadow-elevated: 0 18px 40px rgba(15,28,46,0.12);
  --pv-max: 72rem;
  --pv-content: 40rem;
  --pv-motion: 220ms;
  --pv-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --vg-bg: var(--pv-bg);
  --vg-surface: var(--pv-surface);
  --vg-text: var(--pv-text);
  --vg-muted: var(--pv-muted);
  --vg-border: var(--pv-border);
  --vg-accent: var(--pv-accent);
  --vg-accent-contrast: var(--pv-accent-contrast);
  --vg-accent-hover: var(--pv-accent-hover);
  --vg-focus: var(--pv-focus);
  --vg-max: var(--pv-max);
  --vg-radius: var(--pv-radius-md);
  --vg-shadow: var(--pv-shadow-subtle);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  background: var(--pv-bg);
  color: var(--pv-text);
  font-family: "Iowan Old Style", "Palatino Linotype", "Times New Roman", Georgia, serif;
  font-size: var(--pv-font-body);
  line-height: 1.6;
  overflow-x: hidden;
}
body {
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
}
a { color: var(--pv-accent); }
a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 3px solid var(--pv-focus);
  outline-offset: 2px;
}
.vg-shell, .pv-shell { min-height: 100vh; display: flex; flex-direction: column; }
.vg-container, .pv-container {
  width: min(100% - 2rem, var(--pv-max));
  margin: 0 auto;
